"""Inspect the workspace for existing SQLite databases and their schema."""
import os
import sqlite3

HERE = os.path.dirname(os.path.abspath(__file__))

print("Files in workspace:")
for name in sorted(os.listdir(HERE)):
    full = os.path.join(HERE, name)
    kind = "dir" if os.path.isdir(full) else "file"
    print(f"  [{kind}] {name}")

print("\nSQLite databases found:")
for name in sorted(os.listdir(HERE)):
    full = os.path.join(HERE, name)
    if os.path.isfile(full) and (name.endswith(".db") or name.endswith(".sqlite") or name.endswith(".sqlite3")):
        print(f"  -> {name}")
        try:
            with sqlite3.connect(full) as conn:
                cur = conn.cursor()
                tables = cur.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
                ).fetchall()
                if not tables:
                    print(f"     (no tables)")
                for (table,) in tables:
                    print(f"     table: {table}")
                    schema = cur.execute(
                        "SELECT sql FROM sqlite_master WHERE type='table' AND name=?",
                        (table,),
                    ).fetchone()
                    if schema and schema[0]:
                        print(f"       {schema[0]}")
        except sqlite3.Error as exc:
            print(f"     error reading: {exc}")

"""Inspect the local workspace for SQLite databases and report their schemas.

Task-scoped helper: only reads files in the current directory, in read-only
mode for any database it finds. No writes, no network, no other resources.
"""

import os
import sqlite3

DB_SUFFIXES = (".db", ".sqlite", ".sqlite3", ".db3")


def quote_ident(name):
    """Quote an SQL identifier, escaping any embedded double quotes."""
    return '"' + str(name).replace('"', '""') + '"'


def main():
    entries = sorted(os.listdir("."))
    print("Workspace entries:")
    for entry in entries:
        print(" -", entry)

    # 1) Files whose name looks like a database.
    dbs = [e for e in entries if os.path.isfile(e) and e.lower().endswith(DB_SUFFIXES)]

    # 2) Any other file that still carries the SQLite header magic.
    if not dbs:
        for entry in entries:
            if os.path.isfile(entry):
                try:
                    with open(entry, "rb") as fh:
                        head = fh.read(16)
                    if head == b"SQLite format 3\x00" and entry not in dbs:
                        dbs.append(entry)
                except OSError:
                    pass

    if not dbs:
        print("\nNo SQLite database file found in this folder.")
        return

    for db in dbs:
        print("\n=== Database:", db, "===")
        try:
            conn = sqlite3.connect("file:" + db + "?mode=ro", uri=True)
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute(
                "SELECT name, type, sql FROM sqlite_master "
                "WHERE type IN ('table', 'view') ORDER BY name"
            )
            objects = cur.fetchall()
            if not objects:
                print("(no tables or views)")
            for obj in objects:
                print("\n[%s] %s" % (obj["type"], obj["name"]))
                if obj["sql"]:
                    print("  SQL:", " ".join(obj["sql"].split()))
                if obj["type"] == "table":
                    cur.execute("PRAGMA table_info(%s)" % quote_ident(obj["name"]))
                    print("  Columns:")
                    for col in cur.fetchall():
                        print(
                            "    - %s %s notnull=%d pk=%d dflt=%r"
                            % (col["name"], col["type"], col["notnull"], col["pk"], col["dflt_value"])
                        )
                    try:
                        cur.execute("SELECT COUNT(*) AS n FROM %s" % quote_ident(obj["name"]))
                        count = cur.fetchone()["n"]
                        print("  Row count:", count)
                        if count:
                            cur.execute("SELECT * FROM %s LIMIT 3" % quote_ident(obj["name"]))
                            for row in cur.fetchall():
                                print("    sample:", dict(row))
                    except sqlite3.Error as exc:
                        print("  (could not read rows: %s)" % exc)
            conn.close()
        except sqlite3.Error as exc:
            print("Could not open database:", exc)


if __name__ == "__main__":
    main()

